package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.charset.StandardCharsets;
public class OwnStateSchemaSummaryTest {
 static final String H="a".repeat(64), J="b".repeat(64);
 OwnStateSchemaSummary.Result parse(OwnStateSchemaSummary.Schema s,String data){return OwnStateSchemaSummary.parse(s,data.getBytes(StandardCharsets.UTF_8));}
 String state(){return "{\"schema\":1,\"bootCount\":3,\"day\":\"2026-11-12\",\"runStartedAt\":100,\"readingStartedAt\":0,\"readingAttempts\":0,\"readingNoCredit\":0,\"searchAttempts\":0,\"searchNoCredit\":0,\"searchHashes\":[],\"pendingTask\":\"\",\"pendingBefore\":0,\"pendingTarget\":0,\"pendingHash\":\"\"}";}
 OwnStateSchemaSummary.Result st(String s){return parse(OwnStateSchemaSummary.Schema.STATE_OFFICIAL_JSON,s);}
 void bad(OwnStateSchemaSummary.Result r){assertEquals(OwnStateSchemaSummary.Status.MALFORMED_OR_CHECKSUM_FAILED,r.status());assertFalse(r.actionAllowed());assertEquals(OwnStateSchemaSummary.Pending.UNKNOWN,r.pending());}
 @Test public void validStateOnlySchemaNotPermission(){var r=st(state());assertEquals(OwnStateSchemaSummary.Status.SCHEMA_VALID_HISTORY_UNPROVEN,r.status());assertEquals(3,r.bootCount());assertEquals("2026-11-12",r.day());assertFalse(r.actionAllowed());assertTrue(r.hold());}
 @Test public void completeKeysAndTypes(){bad(st(state().replace("\"schema\":1","\"schema\":1,\"extra\":0")));bad(st(state().replace("\"schema\":1","\"schema\":2")));bad(st(state().replace("\"schema\":1","\"schema\":\"1\"")));bad(st(state().replace("\"bootCount\":3,","")));bad(st(state().replace("\"schema\":1","\"schema\":1.0")));}
 @Test public void duplicateKeysIncludingEscaped(){bad(st(state().replace("\"schema\":1","\"schema\":1,\"schema\":1")));bad(st(state().replace("\"schema\":1","\"schema\":1,\"sch\\u0065ma\":1")));}
 @Test public void malformedJsonAndTrailing(){for(String s:new String[]{state()+"{}",state()+" x",state().replace("100","01"),state().replace("100","null"),state().replace("100","true"),state().replace("100","[]"),state().replace("100","{}"),state().substring(1)})bad(st(s));}
 @Test public void strictUtfAndSize(){bad(OwnStateSchemaSummary.parse(OwnStateSchemaSummary.Schema.STATE_OFFICIAL_JSON,new byte[]{(byte)0xc3,0x28}));bad(OwnStateSchemaSummary.parse(OwnStateSchemaSummary.Schema.STATE_OFFICIAL_JSON,new byte[65537]));bad(OwnStateSchemaSummary.parse(OwnStateSchemaSummary.Schema.STATE_OFFICIAL_JSON,null));bad(st("\ufeff"+state()));}
 @Test public void dateAndNumericBounds(){bad(st(state().replace("2026-11-12","2026-02-30")));bad(st(state().replace("2026-11-12","2026-1-12")));bad(st(state().replace("\"bootCount\":3","\"bootCount\":2147483648")));bad(st(state().replace("\"runStartedAt\":100","\"runStartedAt\":-1")));bad(st(state().replace("\"readingAttempts\":0","\"readingAttempts\":100001")));}
 @Test public void stateCountsAndHashSetMustAgree(){bad(st(state().replace("\"readingNoCredit\":0","\"readingNoCredit\":1")));bad(st(state().replace("\"searchAttempts\":0","\"searchAttempts\":1")));bad(st(state().replace("[]","[\""+H+"\",\""+H+"\"]")));}
 @Test public void pendingReadingPreserved(){String s=state().replace("\"readingAttempts\":0","\"readingAttempts\":1").replace("\"pendingTask\":\"\"","\"pendingTask\":\"READING\"").replace("\"pendingTarget\":0","\"pendingTarget\":30");var r=st(s);assertEquals(OwnStateSchemaSummary.Pending.READING,r.pending());assertEquals(OwnStateSchemaSummary.Status.PENDING_REQUIRES_REVIEW,r.status());assertFalse(r.actionAllowed());bad(st(s.replace("\"pendingBefore\":0","\"pendingBefore\":30")));}
 @Test public void searchPendingMustBindReservedHash(){String s=state().replace("\"searchAttempts\":0","\"searchAttempts\":1").replace("[]","[\""+H+"\"]").replace("\"pendingTask\":\"\"","\"pendingTask\":\"SEARCH\"").replace("\"pendingHash\":\"\"","\"pendingHash\":\""+H+"\"").replace("\"pendingTarget\":0","\"pendingTarget\":60");assertEquals(OwnStateSchemaSummary.Pending.SEARCH,st(s).pending());bad(st(s.replace("\"pendingHash\":\""+H,"\"pendingHash\":\""+J)));assertFalse(st(s).summary().contains(H));}
 @Test public void residueWithoutPendingNeverClean(){bad(st(state().replace("\"pendingBefore\":0","\"pendingBefore\":1")));bad(st(state().replace("\"pendingHash\":\"\"","\"pendingHash\":\""+H+"\"")));bad(st(state().replace("\"pendingTask\":\"\"","\"pendingTask\":\"OTHER\"")));}
 String history(String hashes){return "{\"schema\":1,\"day\":\"2026-11-12\",\"hashes\":"+hashes+"}";}
 @Test public void historyCountsNoHashesExport(){var r=parse(OwnStateSchemaSummary.Schema.READING_HISTORY_JSON,history("[\""+H+"\"]"));assertEquals(1,r.hashCount());assertFalse(r.summary().contains(H));assertFalse(r.actionAllowed());bad(parse(OwnStateSchemaSummary.Schema.READING_HISTORY_JSON,history("[\""+H+"\",\""+H+"\"]")));bad(parse(OwnStateSchemaSummary.Schema.READING_HISTORY_JSON,history("[\"wrong\"]")));}
 @Test public void distinctHistoryLimits(){StringBuilder a=new StringBuilder("[");for(int i=0;i<4;i++){if(i>0)a.append(',');a.append('"').append(String.format("%064x",i)).append('"');}a.append(']');assertEquals(4,parse(OwnStateSchemaSummary.Schema.READING_HISTORY_JSON,history(a.toString())).hashCount());bad(parse(OwnStateSchemaSummary.Schema.WEB_HISTORY_JSON,history(a.toString())));}
 @Test public void morePendingAndResidue(){String base=history("[\""+H+"\"]");base=base.substring(0,base.length()-1)+",\"pendingHash\":\""+H+"\",\"pendingBefore\":0,\"pendingTarget\":20,\"pendingPoints\":5}";assertEquals(OwnStateSchemaSummary.Pending.MORE,parse(OwnStateSchemaSummary.Schema.MORE_HISTORY_JSON,base).pending());bad(parse(OwnStateSchemaSummary.Schema.MORE_HISTORY_JSON,base.replace("\"pendingPoints\":5","\"pendingPoints\":21")));bad(parse(OwnStateSchemaSummary.Schema.MORE_HISTORY_JSON,base.replace("\"pendingHash\":\""+H+"\"","\"pendingHash\":\"\"")));}
 String xml(String status){return "<?xml version='1.0' encoding='utf-8' standalone='yes' ?>\n<map>\n<string name=\"day\">2026-11-12</string>\n<string name=\"status\">"+status+"</string>\n</map>";}
 @Test public void exactCheckinStrings(){var p=parse(OwnStateSchemaSummary.Schema.CHECKIN_XML,xml("pending"));assertEquals(OwnStateSchemaSummary.Pending.CHECKIN,p.pending());assertFalse(p.checkinDone());var d=parse(OwnStateSchemaSummary.Schema.CHECKIN_XML,xml("done"));assertTrue(d.checkinDone());assertFalse(d.actionAllowed());assertEquals(OwnStateSchemaSummary.Status.EMPTY_PREFS_HISTORY_UNPROVEN,parse(OwnStateSchemaSummary.Schema.CHECKIN_XML,"<map />").status());}
 @Test public void xmlRejectsEntityDtdUnknownTypeAndDuplicates(){for(String s:new String[]{xml("other"),xml("pending")+"junk",xml("pending").replace("<map>","<!DOCTYPE map><map>"),xml("&evil;"),xml("done").replace("name=\"status\"","name=\"day\""),xml("done").replace("<string","<int"),xml("done").replace("name=\"day\"","name=\"extra\""),xml("done").replace("2026-11-12","2026-02-30")})bad(parse(OwnStateSchemaSummary.Schema.CHECKIN_XML,s));}
 @Test public void allUnsupportedAreExplicitHold(){for(var s:OwnStateSchemaSummary.Schema.values()){if(s==OwnStateSchemaSummary.Schema.STATE_OFFICIAL_JSON||s==OwnStateSchemaSummary.Schema.READING_HISTORY_JSON||s==OwnStateSchemaSummary.Schema.WEB_HISTORY_JSON||s==OwnStateSchemaSummary.Schema.MORE_HISTORY_JSON||s==OwnStateSchemaSummary.Schema.CHECKIN_XML)continue;var r=OwnStateSchemaSummary.parse(s,new byte[]{1,2});assertEquals(OwnStateSchemaSummary.Status.UNSUPPORTED_SCHEMA,r.status());assertFalse(r.actionAllowed());assertEquals(-1,r.hashCount());}assertEquals(OwnStateSchemaSummary.Schema.UNKNOWN,OwnStateSchemaSummary.parse(null,null).schema());}
 @Test public void syntheticNeverBecomesRealHistory(){var r=OwnStateSchemaSummary.parse(OwnStateSchemaSummary.Schema.SYNTHETIC_ATTEMPT_JOURNAL,state().getBytes(StandardCharsets.UTF_8));assertEquals(OwnStateSchemaSummary.Status.UNSUPPORTED_SCHEMA,r.status());assertEquals("",r.day());assertEquals(-1,r.readingAttempts());}
 @Test public void summaryConstructorRejectsUnboundedText(){try{new OwnStateSchemaSummary.Result(OwnStateSchemaSummary.Schema.UNKNOWN,OwnStateSchemaSummary.Status.UNSUPPORTED_SCHEMA,"secret",-1,OwnStateSchemaSummary.Pending.UNKNOWN,-1,-1,-1,-1,-1,false);fail();}catch(IllegalArgumentException expected){}}
}
